import { useState } from "react";

export function SortableList({
  heading = "{{heading}}",
  accent = "{{accent}}",
  style = "{{style}}",
  showHandle = {{showHandle}},
  gap = {{gap}},
}) {
  const [items, setItems] = useState(["Morning warm-up", "Focus block", "Wind-down"]);
  const move = (i, dir) => {
    const j = i + dir;
    if (j < 0 || j >= items.length) return;
    const next = [...items];
    [next[i], next[j]] = [next[j], next[i]];
    setItems(next);
  };
  const rowStyle = {
    display: "flex", alignItems: "center", gap: 8, padding: "8px 10px", marginBottom: gap, borderRadius: 8,
    background: style === "card" ? "#fff" : "transparent",
    boxShadow: style === "card" ? "0 1px 4px rgba(36,20,48,.08)" : "none",
  };
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", background: "#FAF7F2", maxWidth: 320, width: 320, padding: 16, borderRadius: 12, boxSizing: "border-box" }}>
      <h3 style={{ margin: "0 0 4px", fontSize: 15, fontWeight: 700 }}>{heading}</h3>
      <p style={{ margin: "0 0 10px", fontSize: 12, color: "#241430a0" }}>Use the move buttons to reorder — no dragging required.</p>
      <ol style={{ listStyle: "none", margin: 0, padding: 0 }}>
        {items.map((item, i) => (
          <li key={item} style={rowStyle}>
            {showHandle && <span aria-hidden="true" style={{ color: "#24143070", cursor: "grab" }}>⠿</span>}
            {style === "numbered" && <span style={{ fontWeight: 700, color: accent }}>{i + 1}.</span>}
            <span style={{ flex: 1 }}>{item}</span>
            <span style={{ display: "flex", gap: 2 }}>
              <button type="button" disabled={i === 0} aria-label={`Move ${item} up`} onClick={() => move(i, -1)} style={{ width: 24, height: 24, borderRadius: 6, border: "1px solid #24143020", background: "#fff", cursor: i === 0 ? "not-allowed" : "pointer", opacity: i === 0 ? 0.35 : 1, fontSize: 12 }}>↑</button>
              <button type="button" disabled={i === items.length - 1} aria-label={`Move ${item} down`} onClick={() => move(i, 1)} style={{ width: 24, height: 24, borderRadius: 6, border: "1px solid #24143020", background: "#fff", cursor: i === items.length - 1 ? "not-allowed" : "pointer", opacity: i === items.length - 1 ? 0.35 : 1, fontSize: 12 }}>↓</button>
            </span>
          </li>
        ))}
      </ol>
    </div>
  );
}
